// Edit searches and engines here. Operators are passed to the search engine unchanged.
const config = {
  endpoint: $env.SEARXNG_URL || 'https://searx.be/search',
  engines: ['google', 'bing', 'brave'],
  searches: [
    { expression: '(n8n OR automation) AND \"web search\"', matchingKeywords: ['n8n', 'automation', 'web search'] },
    { expression: '(AI OR LLM) AND (agent OR workflow) -job', matchingKeywords: ['AI', 'LLM', 'agent', 'workflow'] }
  ]
};

return config.searches.map((search) => {
  const url = new URL(config.endpoint);
  url.searchParams.set('format', 'json');
  url.searchParams.set('q', search.expression);
  url.searchParams.set('engines', config.engines.join(','));
  return { json: { ...search, engines: config.engines, url: url.toString() } };
});

// SearXNG returns one response per logical expression, with a source engine on each result.
// Workflow static data survives production executions and provides durable de-duplication.
const staticData = $getWorkflowStaticData('global');
staticData.seen ??= {};
const now = new Date();
const searched = $items('Build logical searches', 0, 0);
const searchByExpression = new Map(searched.map(({ json }) => [json.expression, json]));
const output = [];

for (const item of $input.all()) {
  const response = item.json;
  const search = searchByExpression.get(response.query);
  if (!search || !Array.isArray(response.results)) continue;

  for (const result of response.results) {
    const link = result.url || result.link;
    if (!link) continue;
    const key = link.replace(/#.*$/, '').replace(/\/$/, '').toLowerCase();
    if (staticData.seen[key]) continue;
    staticData.seen[key] = now.toISOString();

    output.push({
      json: {
        date: now.toISOString().slice(0, 10),
        time: now.toISOString().slice(11, 19) + ' UTC',
        query: search.expression,
        matchingKeywords: search.matchingKeywords.join(', '),
        engine: result.engine || result.engines?.join(', ') || 'SearXNG',
        title: String(result.title || link).replace(/\s+/g, ' ').trim(),
        link,
        lead: String(result.content || result.snippet || '').replace(/\s+/g, ' ').trim()
      }
    });
  }
}
return output;

const rows = $input.all().map(({ json }) => {
  const safeTitle = json.title.replace(/[
]+/g, ' ');
  const safeLead = json.lead.replace(/[
]+/g, ' ');
  return `## ${json.date} ${json.time} — ${safeTitle}

- **Matching keywords:** ${json.matchingKeywords}
- **Query:** ${json.query}
- **Search engine:** ${json.engine}
- **Link:** [Open result](${json.link})
- **Lead:** ${safeLead}
`;
});
if (!rows.length) return [];
const markdown = `
${rows.join('
')}
`;
return [{ json: { markdownBase64: Buffer.from(markdown, 'utf8').toString('base64'), resultCount: rows.length } }];
